--   CCD-01411: "2612126182" parece un teléfono, no un documento

BEGIN;

CREATE TEMP TABLE _stg_cec_v3 (
  codigo_interno TEXT PRIMARY KEY,
  nombre         TEXT NOT NULL,
  apellido       TEXT NOT NULL,
  nombre_usuario TEXT,
  modo           TEXT,
  conf_codigo    TEXT,
  frat_codigo    TEXT,
  email          TEXT,
  telefono       TEXT,
  tipo_documento TEXT,
  documento      TEXT
) ON COMMIT DROP;


-- ─── 1. Altas nuevas (códigos que todavía no existen) ─────────────────────────
-- nombre_usuario en ASCII (ñ→n, sin tildes), igual que create_cecista_logins.mjs.
CREATE TEMP TABLE _nuevas_v3 ON COMMIT DROP AS
SELECT s.codigo_interno
  FROM _stg_cec_v3 s
 WHERE NOT EXISTS (SELECT 1 FROM public.personas p WHERE p.codigo_interno = s.codigo_interno);

SELECT s.codigo_interno, s.nombre, s.apellido,
       CASE WHEN u.usr IS NOT NULL
             AND NOT EXISTS (SELECT 1 FROM public.personas x WHERE x.nombre_usuario = u.usr)
            THEN u.usr END,
       'cecista', 'activo'
  FROM _stg_cec_v3 s
  JOIN _nuevas_v3 n USING (codigo_interno)
  CROSS JOIN LATERAL (
    SELECT lower(translate(s.nombre_usuario, 'ñÑáéíóúÁÉÍÓÚäëïöüÄËÏÖÜ', 'nnaeiouaeiouaeiouaeiou')) AS usr
  ) u
ON CONFLICT (codigo_interno) WHERE codigo_interno IS NOT NULL DO NOTHING;

SELECT p.id, s.modo, CURRENT_DATE, 'activo'
  FROM _stg_cec_v3 s
  JOIN _nuevas_v3 n USING (codigo_interno)
  JOIN public.personas p ON p.codigo_interno = s.codigo_interno
 WHERE s.modo IS NOT NULL;

SELECT p.id, o.id, 'confraternidad', CURRENT_DATE
  FROM _stg_cec_v3 s
  JOIN _nuevas_v3 n USING (codigo_interno)
  JOIN public.personas p       ON p.codigo_interno = s.codigo_interno
  JOIN public.organizaciones o ON o.codigo = s.conf_codigo AND o.tipo = 'confraternidad';

SELECT p.id, o.id, 'fraternidad', CURRENT_DATE
  FROM _stg_cec_v3 s
  JOIN _nuevas_v3 n USING (codigo_interno)
  JOIN public.personas p       ON p.codigo_interno = s.codigo_interno
  JOIN public.organizaciones o ON o.codigo = s.frat_codigo AND o.tipo = 'fraternidad';

-- ─── 2. Completar email / teléfono / documento (solo donde falta) ─────────────
UPDATE public.personas p
   SET email = CASE
         WHEN p.email IS NULL AND s.email IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM public.personas x
                           WHERE lower(x.email) = s.email AND x.id <> p.id)
         THEN s.email ELSE p.email END,
       telefono = COALESCE(p.telefono, s.telefono),
       tipo_documento = CASE
         WHEN p.tipo_documento IS NULL AND s.tipo_documento IS NOT NULL
          AND (p.documento = s.documento
               OR (p.documento IS NULL
                   AND NOT EXISTS (SELECT 1 FROM public.personas x
                                    WHERE x.documento = s.documento AND x.id <> p.id)))
         THEN s.tipo_documento ELSE p.tipo_documento END,
       documento = CASE
         WHEN p.documento IS NULL AND s.documento IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM public.personas x
                           WHERE x.documento = s.documento AND x.id <> p.id)
         THEN s.documento ELSE p.documento END,
       updated_at = now()
  FROM _stg_cec_v3 s
 WHERE p.codigo_interno = s.codigo_interno
   AND (   (p.email IS NULL          AND s.email IS NOT NULL)
        OR (p.telefono IS NULL       AND s.telefono IS NOT NULL)
        OR (p.tipo_documento IS NULL AND s.tipo_documento IS NOT NULL)
        OR (p.documento IS NULL      AND s.documento IS NOT NULL));

-- ─── 3. Correcciones de nombre de la planilla (solo si nadie lo editó) ────────
UPDATE public.personas SET apellido = 'Porchietto', updated_at = now()
 WHERE codigo_interno = 'CCD-01114' AND apellido = 'Porchierto';
UPDATE public.personas SET nombre = 'Juan Carlos', updated_at = now()
 WHERE codigo_interno = 'CCD-01879' AND nombre = 'Juan';

COMMIT;

